import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosKbd, KozmosText } from "../../index";

/**
 * Vue's Kbd: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Kbd`; InAHint drawn by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Data display/Kbd",
  component: KozmosKbd,
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosKbd, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "Esc",
  },
};

export const Combination: Story = {
  args: {
    children: "Esc",
    keys: ["Ctrl", "Shift", "P"],
  },
};

/**
 * React's InAHint: Esc drawn as a key and read "Escape" (GAP-156). Drawn
 * with a render function, not a template, so its text is React's to the
 * node: a template trims nothing at the sentence's ends and joins React's
 * `{" "}` with the words after it into one text node, which Chromium lays
 * out a fraction of a pixel differently (PR #610's baselines).
 */
export const InAHint: Story = {
  render: () => ({
    setup: () => () =>
      h(KozmosText, { size: "sm", color: "muted" }, () => [
        "Press ",
        h(KozmosKbd, null, () => "Esc"),
        " to clear the selection, or ",
        h(KozmosKbd, { keys: ["⌘", "A"] }),
        " ",
        "to select every feature.",
      ]),
  }),
};
